const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const geometry = ee.Geometry.Rectangle([-121, 32, -114, 35]); // Southern California
    const startDate2003 = '2003-04-14';
    const endDate2003 = '2003-04-21';
    const startDate2004 = '2004-04-14';
    const endDate2004 = '2004-04-21';

    // 2. Data Acquisition & Check
    const modisLST = ee.ImageCollection('MODIS/061/MOD11A1');

    // Function to mask low-quality pixels
    const maskLST = function(image) {
        const quality = image.select('QC_Day');
        // Keep pixels where bits 0-1 are 0 (good quality)
        const mask = quality.bitwiseAnd(0b11).eq(0);
        return image.updateMask(mask);
    };

    // Process 2003 data
    const collection2003 = modisLST.filterDate(startDate2003, endDate2003).map(maskLST);
    const collection2003Size = collection2003.size().getInfo();
    if (collection2003Size === 0) {
        console.log("No images found for 2003 period.");
        console.log("A: No");
        return;
    }
    const image2003 = collection2003.select('LST_Day_1km').median();

    // Process 2004 data
    const collection2004 = modisLST.filterDate(startDate2004, endDate2004).map(maskLST);
    const collection2004Size = collection2004.size().getInfo();
    if (collection2004Size === 0) {
        console.log("No images found for 2004 period.");
        console.log("A: No");
        return;
    }
    const image2004 = collection2004.select('LST_Day_1km').median();

    // 3. Calculation & Pixel Count Check
    const scale = 1000;
    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const stats2003 = image2003.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    const stats2004 = image2004.reduceRegion({
        reducer: reducer,
        geometry: geometry,
        scale: scale,
        maxPixels: 1e9
    });

    const lst2003 = stats2003.get('LST_Day_1km_mean').getInfo();
    const count2003 = stats2003.get('LST_Day_1km_count').getInfo();

    const lst2004 = stats2004.get('LST_Day_1km_mean').getInfo();
    const count2004 = stats2004.get('LST_Day_1km_count').getInfo();

    // 4. Validation & Final Answer
    if (count2003 === 0 || count2004 === 0) {
        console.log(`Valid pixels 2003: ${count2003}`);
        console.log(`Valid pixels 2004: ${count2004}`);
        console.log("C2: No Valid Pixels");
        return;
    }

    if (lst2003 === null || lst2004 === null) {
        console.log("Calculation failed, result is null.");
        console.log("C3: Calculation Failure");
        return;
    }

    // LST is in Kelvin with a scale factor of 0.02
    const tempC2003 = (lst2003 * 0.02) - 273.15;
    const tempC2004 = (lst2004 * 0.02) - 273.15;

    console.log(`Image Count 2003: ${collection2003Size}`);
    console.log(`Image Count 2004: ${collection2004Size}`);
    console.log(`Valid Pixel Count 2003: ${count2003}`);
    console.log(`Valid Pixel Count 2004: ${count2004}`);
    console.log(`2003 Avg. LST: ${tempC2003.toFixed(2)} C`);
    console.log(`2004 Avg. LST: ${tempC2004.toFixed(2)} C`);

    if (tempC2004 > tempC2003) {
        console.log("A: Yes");
    } else {
        console.log("B: No");
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`Error: ${e}`);
    console.log("D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.");
});
